 (p/"observer.py").write_text('"""Controlled normal-controller verification, NOT natural systemd timer proof.\n\nRun only after the deployment lock has been released and root approves execution.\nEach original controller runs in a separate process. No runtime source is patched.\n"""\nimport argparse\nimport contextlib\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport runpy\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\n\ndef file_hash(path):\n    p = Path(path)\n    if p.is_symlink() or not p.is_file():\n        return None\n    return hashlib.sha256(p.read_bytes()).hexdigest()\n\n\ndef snapshot_matches(files):\n    for name, sha in files.items():\n        p = Path(name)\n        if sha is None:\n            if p.exists() or p.is_symlink():\n                return False\n        elif file_hash(name) != sha:\n            return False\n    return True\n\n\ndef child_observer(spec):\n    import fcntl\n    result = {\'controller\': spec[\'path\'], \'mode\': \'controlled-original-code\',\n              \'acquired_target_lock\': False, \'lock_observations\': [], \'exit_code\': None}\n    before = file_hash(spec[\'path\'])\n    result[\'source_before\'] = before\n    if before != spec[\'sha256\'] or not snapshot_matches(spec[\'files\']):\n        result.update(status=\'FAIL\', reason=\'source-precheck\', exit_code=78)\n        return result, 78\n    lock_stat = os.stat(spec[\'lock_path\'])\n    target = (lock_stat.st_dev, lock_stat.st_ino)\n    original = fcntl.flock\n\n    def observed(fd, operation):\n        # Preserve original return and exceptions. Observation happens only AFTER\n        # the real syscall returned successfully; lock-busy SystemExit(0) cannot pass.\n        value = original(fd, operation)\n        try:\n            info = os.fstat(fd if isinstance(fd, int) else fd.fileno())\n            if (info.st_dev, info.st_ino) == target and operation & fcntl.LOCK_EX:\n                result[\'acquired_target_lock\'] = True\n                result[\'lock_observations\'].append({\'source_hash\': file_hash(spec[\'path\']),\n                                                    \'snapshot_matches\': snapshot_matches(spec[\'files\'])})\n        except BaseException as error:\n            # Observer failures invalidate acceptance, never change controller flow.\n            result[\'observer_error_type\'] = type(error).__name__\n        return value\n\n    stdout, stderr = io.StringIO(), io.StringIO()\n    code = 0\n    fcntl.flock = observed\n    try:\n        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):\n            runpy.run_path(spec[\'path\'], run_name=\'__main__\')\n    except SystemExit as error:\n        code = error.code if isinstance(error.code, int) else (0 if error.code is None else 1)\n    except BaseException as error:\n        result[\'controller_error_type\'] = type(error).__name__\n        code = 1\n    finally:\n        fcntl.flock = original\n    result.update(exit_code=code, source_after=file_hash(spec[\'path\']),\n                  final_snapshot_matches=snapshot_matches(spec[\'files\']),\n                  stdout_characters=len(stdout.getvalue()), stderr_characters=len(stderr.getvalue()))\n    # Do not emit captured output: the original controller may contain credentials.\n    ok = (code == 0 and result[\'acquired_target_lock\'] and not result.get(\'observer_error_type\')\n          and result[\'source_after\'] == spec[\'sha256\'] and result[\'final_snapshot_matches\']\n          and all(v[\'source_hash\'] == spec[\'sha256\'] and v[\'snapshot_matches\'] for v in result[\'lock_observations\']))\n    result[\'status\'] = \'PASS\' if ok else \'FAIL\'\n    return result, code\n\n\ndef inspect_containers(expected):\n    p = subprocess.run([\'docker\', \'inspect\'] + list(expected), stdout=subprocess.PIPE,\n                       stderr=subprocess.PIPE, timeout=8)\n    if p.returncode:\n        raise RuntimeError(\'container-inspection-failed\')\n    values = json.loads(p.stdout)\n    rows = []\n    for item in values:\n        name = item[\'Name\'].lstrip(\'/\')\n        if name not in expected or item[\'Image\'] != expected[name]:\n            raise RuntimeError(\'candidate-image-drift\')\n        if not item[\'State\'][\'Running\'] or item[\'State\'].get(\'Health\', {}).get(\'Status\') != \'healthy\':\n            raise RuntimeError(\'container-unhealthy\')\n        rows.append({\'name\': name, \'id\': item[\'Id\'], \'image\': item[\'Image\'],\n                     \'started_at\': item[\'State\'][\'StartedAt\'], \'restart_count\': item[\'RestartCount\']})\n    if len(rows) != len(expected):\n        raise RuntimeError(\'container-set-changed\')\n    return sorted(rows, key=lambda row: row[\'name\'])\n\n\ndef verify(spec):\n    result = {\'mode\': \'two controlled normal reconciliations, not natural timer invocations\',\n              \'status\': \'FAIL\', \'functional_acceptance\': \'pending-HTTP-HA-device-tests\',\n              \'rounds\': [], \'container_samples\': [], \'no_automatic_rollback\': True}\n    if spec.get(\'round_gap_seconds\', 22) < 22 or spec.get(\'stable_seconds\', 60) < 60:\n        raise ValueError(\'Minimum observation windows cannot be shortened\')\n    if len(spec[\'controllers\']) != 2 or len(spec[\'containers\']) != 2:\n        raise ValueError(\'Exactly two controllers and owner/broker containers required\')\n    baseline = None\n\n    def sample():\n        nonlocal baseline\n        if not snapshot_matches(spec[\'files\']):\n            raise RuntimeError(\'controller-snapshot-drift\')\n        values = inspect_containers(spec[\'containers\'])\n        if baseline is None:\n            baseline = values\n        elif values != baseline:\n            raise RuntimeError(\'container-identity-or-restart-drift\')\n        result[\'container_samples\'].append({\'monotonic\': time.monotonic(), \'containers\': values})\n\n    def observe_wait(seconds):\n        deadline = time.monotonic() + seconds\n        while True:\n            sample()\n            remaining = deadline - time.monotonic()\n            if remaining <= 0:\n                break\n            time.sleep(min(2, remaining))\n\n    try:\n        sample()\n        for round_index in range(2):\n            if round_index:\n                observe_wait(spec.get(\'round_gap_seconds\', 22))\n            record = {\'round\': round_index + 1, \'controllers\': []}\n            result[\'rounds\'].append(record)\n            for controller in spec[\'controllers\']:\n                sample()\n                child_spec = dict(controller, files=spec[\'files\'], lock_path=spec[\'lock_path\'])\n                # Files avoid pipe blocking. Never kill a controller in the middle\n                # of its normal reconciliation merely because health has changed.\n                with tempfile.TemporaryFile() as child_out, tempfile.TemporaryFile() as child_err:\n                    process = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), \'--child\'],\n                                               stdin=subprocess.PIPE, stdout=child_out, stderr=child_err,\n                                               start_new_session=True)\n                    process.stdin.write(json.dumps(child_spec).encode())\n                    process.stdin.close()\n                    started = time.monotonic()\n                    sample_failure = None\n                    while process.poll() is None:\n                        try:\n                            sample()\n                        except Exception as error:\n                            sample_failure = str(error) if isinstance(error, RuntimeError) else \'observation-failed\'\n                        if time.monotonic() - started >= 90:\n                            result[\'still_running_controller\'] = {\'pid\': process.pid, \'path\': controller[\'path\'],\n                                                                  \'action\': \'left running; no kill or rollback\'}\n                            raise RuntimeError(\'controller-timeout-observation-pending\')\n                        time.sleep(2)\n                    child_out.seek(0)\n                    observation = json.loads(child_out.read())\n                observation[\'process_returncode\'] = process.returncode\n                observation[\'elapsed_seconds\'] = time.monotonic() - started\n                record[\'controllers\'].append(observation)\n                if observation.get(\'status\') != \'PASS\' or process.returncode != 0:\n                    raise RuntimeError(\'controller-normal-execution-not-proven\')\n                if sample_failure:\n                    raise RuntimeError(sample_failure)\n                sample()\n        # Stable runtime throughout execution PLUS at least60s after the final pass.\n        observe_wait(spec.get(\'stable_seconds\', 60))\n        result[\'status\'] = \'PASS\'\n    except Exception as error:\n        result[\'error_type\'] = type(error).__name__\n        result[\'reason\'] = str(error) if isinstance(error, RuntimeError) else \'verification-failed\'\n    return result\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--child\', action=\'store_true\')\n    parser.add_argument(\'--spec\')\n    parser.add_argument(\'--output\')\n    args = parser.parse_args()\n    if args.child:\n        answer, exit_code = child_observer(json.load(sys.stdin))\n        print(json.dumps(answer))\n        sys.exit(exit_code)\n    if not args.spec or not args.output:\n        parser.error(\'--spec and --output required; execution needs root approval\')\n    answer = verify(json.loads(Path(args.spec).read_text()))\n    Path(args.output).write_text(json.dumps(answer, indent=2))\n    print(json.dumps({\'status\': answer[\'status\'], \'mode\': answer[\'mode\']}))\n    sys.exit(0 if answer[\'status\'] == \'PASS\' else 1)\n')
 (p/"spec.json").write_text('{\r\n  "lock_path": "/opt/tp-community-actions/deployment.lock",\r\n  "files": {\r\n    "/opt/tp-community-main-20261028/http-runtime/scope.py": "4942a20e28557ff9275580018cfc58fc5eb54a522e7740e9f9d4d8f5607edcb2",\r\n    "/opt/tp-community-main-20261028/ha-runtime/scope.py": "6331a89ee2d148eb58f101615f277059a82c74b2bcd94241b47fab5e0fd80997",\r\n    "/opt/tp-community-main-20261028/http-runtime/broker_scope_roles.py": null,\r\n    "/opt/tp-community-main-20261028/ha-runtime/broker_scope_roles.py": null\r\n  },\r\n  "controllers": [\r\n    {\r\n      "path": "/opt/tp-community-main-20261028/http-runtime/scope.py",\r\n      "sha256": "4942a20e28557ff9275580018cfc58fc5eb54a522e7740e9f9d4d8f5607edcb2"\r\n    },\r\n    {\r\n      "path": "/opt/tp-community-main-20261028/ha-runtime/scope.py",\r\n      "sha256": "6331a89ee2d148eb58f101615f277059a82c74b2bcd94241b47fab5e0fd80997"\r\n    }\r\n  ],\r\n  "containers": {\r\n    "tp-community-main-47-broker-owner-1": "sha256:9eacef06c41998668296d4a5da3a4081a2ec7a351e86dd3bc7315b3f89962871",\r\n    "tp-community-main-47-broker-mosquitto-1": "sha256:9eacef06c41998668296d4a5da3a4081a2ec7a351e86dd3bc7315b3f89962871"\r\n  },\r\n  "round_gap_seconds": 22,\r\n  "stable_seconds": 60\r\n}')
